package com.finflow.account; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="accounts") class Account{@Id UUID id; UUID customerId; String currency; BigDecimal postedBalance; BigDecimal availableBalance; String status; @Version long version; Instant updatedAt; protected Account(){} void debit(BigDecimal a){if(!"ACTIVE".equals(status))throw new IllegalArgumentException("Account not active");if(availableBalance.compareTo(a)<0)throw new IllegalArgumentException("Insufficient funds");postedBalance=postedBalance.subtract(a);availableBalance=availableBalance.subtract(a);updatedAt=Instant.now();} void credit(BigDecimal a){postedBalance=postedBalance.add(a);availableBalance=availableBalance.add(a);updatedAt=Instant.now();}}